/* ============================================================
   RIO FastAPI Frontend - JavaScript (Minimal UI)
   ============================================================ */

const API_URL = "http://0.0.0.0:8000";
let isProcessing = false;
let mediaRecorder = null;
let audioChunks = [];

// ============================================================
// INITIALIZE
// ============================================================

document.addEventListener("DOMContentLoaded", () => {
    console.log(" RIO initialized");
    console.log(`API URL: ${API_URL}`);
    setupEventListeners();
});

function setupEventListeners() {
    const userInput = document.getElementById("userInput");
    const sendBtn = document.getElementById("sendBtn");

    if (!userInput || !sendBtn) {
        console.error("❌ Missing DOM elements!");
        return;
    }

    sendBtn.addEventListener("click", () => {
        console.log(" Send button clicked");
        sendMessage();
    });

    userInput.addEventListener("keypress", (e) => {
        if (e.key === "Enter" && !isProcessing) {
            console.log(" Enter key pressed");
            sendMessage();
        }
    });

    console.log("✅ Event listeners attached");
}

// ============================================================
// SEND MESSAGE
// ============================================================

async function sendMessage() {
    const userInput = document.getElementById("userInput");
    const text = userInput.value.trim();

    if (!text) return;
    if (isProcessing) return;

    isProcessing = true;
    document.getElementById("sendBtn").disabled = true;

    try {
        // Clear input
        userInput.value = "";

        // Show loading
        const responseDiv = document.getElementById("rioResponse");
        responseDiv.innerHTML = '<span style="opacity: 0.6;">Thinking...</span>';

        // Send request
        const response = await fetch(`${API_URL}/api/exchange`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                text: text,
                face_emotion: null,
                face_confidence: 0.5,
                voice_emotion: null,
                voice_confidence: 0.5
            })
        });

        if (!response.ok) {
            throw new Error(`API error: ${response.status}`);
        }

        const data = await response.json();

        // Update emotion display
        updateEmotionDisplay(data);

        // Update response
        responseDiv.textContent = data.dialogue_response;

        // Play audio if available
        if (data.audio_file) {
            playAudio(data.audio_file);
        }

    } catch (error) {
        console.error("Error:", error);
        document.getElementById("rioResponse").textContent = "❌ Something went wrong. Please try again.";
    } finally {
        isProcessing = false;
        document.getElementById("sendBtn").disabled = false;
        document.getElementById("userInput").focus();
    }
}

// ============================================================
// EMOTION DISPLAY
// ============================================================

function updateEmotionDisplay(data) {
    const emotionState = document.getElementById("emotionState");
    const eyesImg = document.getElementById("eyesImg");
    const mouthImg = document.getElementById("mouthImg");

    const emotion = data.stimulus_emotion || "neutral";
    const valence = data.stimulus_valence || 0;

    // Update emotion description
    const descriptions = {
        "joy": "Happy and warm",
        "sadness": "Gentle and understanding",
        "anger": "Firm but caring",
        "fear": "Supportive and calm",
        "surprise": "Attentive and curious",
        "disgust": "Thoughtful",
        "neutral": "Warm and receptive"
    };

    emotionState.textContent = descriptions[emotion] || "Responsive";

    // Update animation based on emotion
    const emotionAssets = {
        "joy": {
            eyes: "/assets/animatedEyes/happyEyesVeryGIF.gif",
            mouth: "/assets/animatedNoSpeeches/happy_notSpeakGIF.gif"
        },
        "sadness": {
            eyes: "/assets/animatedEyes/sadEyesSlightGIF.gif",
            mouth: "/assets/animatedNoSpeeches/sad_notSpeakGIF.gif"
        },
        "anger": {
            eyes: "/assets/animatedEyes/angryEyesVeryGIF.gif",
            mouth: "/assets/animatedNoSpeeches/angry_notSpeakGIF.gif"
        },
        "fear": {
            eyes: "/assets/animatedEyes/afraidEyesVeryGIF.gif",
            mouth: "/assets/animatedNoSpeeches/angry_notSpeakGIF.gif"
        },
        "surprise": {
            eyes: "/assets/animatedEyes/surprisedEyesVeryGIF.gif",
            mouth: "/assets/animatedNoSpeeches/happy_notSpeakGIF.gif"
        },
        "disgust": {
            eyes: "/assets/animatedEyes/disgustedEyesVeryGIF.gif",
            mouth: "/assets/animatedNoSpeeches/angry_notSpeakGIF.gif"
        },
        "neutral": {
            eyes: "/assets/animatedEyes/neutralEyesGIF.gif",
            mouth: "/assets/animatedNoSpeeches/happy_notSpeakGIF.gif"
        }
    };

    const assets = emotionAssets[emotion] || emotionAssets["neutral"];
    eyesImg.src = assets.eyes;
    mouthImg.src = assets.mouth;

    // Log emotion vectors to console
    logEmotionVectors(data);
}

// ============================================================
// EMOTION VECTOR LOGGING
// ============================================================

function logEmotionVectors(data) {
    console.log(`
╔════════════════════════════════════════════════════════════╗
║                    EMOTION VECTORS                        ║
╚════════════════════════════════════════════════════════════╝

 User Input: "${data.user_input}"

️  FUSED EMOTION:
    - Dominant: ${data.stimulus_emotion}
    - Valence: ${data.stimulus_valence.toFixed(2)}
    - Confidence: ${(data.stimulus_confidence * 100).toFixed(0)}%

 RIO ENGINE:
    - Intent: ${data.rio_intent}
    - Language: ${data.language}

 Response:
    "${data.dialogue_response}"

 Audio: ${data.audio_file ? "✓ Generated" : "✗ None"}
    `);
}

// ============================================================
// AUDIO PLAYER
// ============================================================

function playAudio(filename) {
    const audioSection = document.getElementById("audioSection");
    const audioPlayer = document.getElementById("audioPlayer");

    audioPlayer.src = `/audio/${filename}`;
    audioSection.classList.add("active");
    audioPlayer.play().catch((err) => {
        console.warn("Audio autoplay prevented:", err);
    });
}

// ============================================================
// MICROPHONE INPUT (Voice-to-Text)
// ============================================================

async function toggleMicrophone() {
    const micBtn = document.getElementById("micBtn");

    if (mediaRecorder === null) {
        // Start recording
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            mediaRecorder = new MediaRecorder(stream);
            audioChunks = [];

            mediaRecorder.ondataavailable = (event) => {
                audioChunks.push(event.data);
            };

            mediaRecorder.onstop = async () => {
                const audio = new Blob(audioChunks, { type: "audio/wav" });
                await transcribeAudio(audio);
                mediaRecorder = null;
            };

            mediaRecorder.start();
            micBtn.textContent = " Recording...";
            micBtn.style.opacity = "0.7";

            // Auto-stop after 10 seconds
            setTimeout(() => {
                if (mediaRecorder) {
                    mediaRecorder.stop();
                }
            }, 10000);

        } catch (error) {
            console.error("Microphone error:", error);
            alert("Microphone access denied");
        }
    } else {
        // Stop recording
        mediaRecorder.stop();
        micBtn.textContent = "";
        micBtn.style.opacity = "1";
    }
}

async function transcribeAudio(audioBlob) {
    const micBtn = document.getElementById("micBtn");
    micBtn.disabled = true;

    try {
        const formData = new FormData();
        formData.append("file", audioBlob, "audio.wav");

        const response = await fetch(`${API_URL}/api/voice/transcribe`, {
            method: "POST",
            body: formData
        });

        const data = await response.json();

        if (data.success) {
            // Auto-send transcribed text
            document.getElementById("userInput").value = data.text;
            await sendMessage();
        } else {
            console.warn("Transcription failed:", data.error);
            alert("Could not understand. Please try again.");
        }

    } catch (error) {
        console.error("Transcription error:", error);
    } finally {
        micBtn.disabled = false;
    }
}
