                voice_confidence: 0.5
            })
        });

        if (!response.ok) {
            throw new Error(`API error: ${response.status}`);
        }

        const data = await response.json();

        log("✅ Exchange complete", "success");
        log(`️ Stimulus: ${data.stimulus_emotion.toUpperCase()} (${(data.stimulus_valence).toFixed(2)})`);
        log(`⚡ Intent: ${data.rio_intent.toUpperCase()}`);
