async function toggleMicrophone() {
    const micBtn = document.getElementById("micBtn");

    if (mediaRecorder === null) {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            mediaRecorder = new MediaRecorder(stream);
            audioChunks = [];

            mediaRecorder.ondataavailable = (event) => {
                audioChunks.push(event.data);
            };

            mediaRecorder.onstop = async () => {
                const audio = new Blob(audioChunks, { type: "audio/wav" });
                await transcribeAudio(audio);
                mediaRecorder = null;
                micBtn.classList.remove("recording");
                micBtn.textContent = "";
            };

            mediaRecorder.start();
            micBtn.classList.add("recording");
            micBtn.textContent = "Recording";

            setTimeout(() => {
                if (mediaRecorder) {
                    mediaRecorder.stop();
                }
            }, 10000);
        } catch (error) {
            console.error("Microphone error:", error);
            alert("Microphone access denied");
        }
    } else {
        mediaRecorder.stop();
    }
}

async function transcribeAudio(audioBlob) {
    const micBtn = document.getElementById("micBtn");
    micBtn.disabled = true;

    try {
        const formData = new FormData();
        formData.append("file", audioBlob, "audio.wav");

        const response = await fetch(`${API_URL}/api/voice/transcribe`, {
            method: "POST",
            body: formData
        });

        const data = await response.json();

        if (data.success) {
            document.getElementById("userInput").value = data.text;
            await sendMessage();
        } else {
            alert("Could not understand. Please try again.");
        }
    } catch (error) {
        console.error("Transcription error:", error);
    } finally {
        micBtn.disabled = false;
    }
}

"""
face_detector.py (v5 — hybrid learned model + landmark geometry)

Architecture:
  PRIMARY  : ONNX emotion model (MobileNet fine-tuned on RAF-DB / AffectNet)
             → stable, generalises across glasses/lighting/skin tone
  SECONDARY: MediaPipe FaceMesh landmark geometry (v4 rules)
             → personal-baseline calibrated, no model needed, used as blend/fallback

Fusion:
  model_confidence >= 0.45  →  80% model  / 20% geometry
  model_confidence  0.25–0.45 → 55% model  / 45% geometry
  model_confidence  < 0.25  →  25% model  / 75% geometry
  model unavailable          → 100% geometry

Temporal smoothing:
  EMA (alpha=0.35) applied per-frame.
  Hysteresis (margin=0.12): dominant label only switches when new leader
  exceeds current leader by 0.12 — prevents rapid flicker.

Model:
  Downloaded on first run from Hugging Face Hub (~12 MB ONNX).
  Cached at ~/.rio_models/face_emotion.onnx
  Falls back gracefully to geometry-only if download fails.
  Requires: pip install huggingface_hub onnxruntime
"""

import cv2
import logging
import math
import time
import sys
from pathlib import Path
from typing import Optional, List, Dict, Tuple

if __name__ == "__main__":
    sys.path.insert(0, str(Path(__file__).parent.parent))

from perception.emotion_fusion import EmotionVector

try:
    from config import FACE_SAMPLE_INTERVAL_S
except Exception:
    FACE_SAMPLE_INTERVAL_S = 3.0

logger = logging.getLogger("FaceDetector")

# ── Model config ──────────────────────────────────────────────────────────────
MODEL_DIR  = Path(__file__).parent / "rio_models"
MODEL_PATH = MODEL_DIR / "face_emotion.onnx"

HF_SOURCES = [
    (
        "onnxmodelzoo/emotion-ferplus-8",
        "model/emotion-ferplus-8.onnx",
        ["neutral", "happiness", "surprise", "sadness", "anger", "disgust", "fear", "contempt"],
    ),
]

LABEL_TO_FIELD: Dict[str, str] = {
    "happiness": "joy",   "happy": "joy",      "joy": "joy",
    "sadness":   "sadness", "sad": "sadness",
    "anger":     "anger",   "angry": "anger",
    "fear":      "fear",    "fearful": "fear",
    "surprise":  "surprise","surprised": "surprise",
    "disgust":   "disgust", "disgusted": "disgust", "contempt": "disgust",
    "neutral":   "neutral", "calm": "neutral",
}

MODEL_INPUT_SIZE = (64, 64)   # emotion-ferplus-8 expects 64×64 grayscale

# ── Smoothing config ──────────────────────────────────────────────────────────

EMA_ALPHA         = 0.35
HYSTERESIS_MARGIN = 0.12


# ── Geometry helper ───────────────────────────────────────────────────────────

def _dist(p1, p2) -> float:
    return math.sqrt((p1.x - p2.x) ** 2 + (p1.y - p2.y) ** 2)


# ── Model downloader ──────────────────────────────────────────────────────────

def _download_model() -> Optional[Tuple[Path, List[str]]]:
    import urllib.request

    MODEL_DIR.mkdir(parents=True, exist_ok=True)

    for url, labels in MODEL_URLS:
        try:
            logger.info(f"Downloading model from {url} ...")
            dest = MODEL_DIR / "face_emotion.onnx"
            tmp  = MODEL_DIR / "face_emotion.onnx.tmp"
            req = urllib.request.Request(url, headers={"User-Agent": "rio-face-detector/1.0"})
            with urllib.request.urlopen(req, timeout=120) as resp, open(tmp, "wb") as f:
                while True:
                    chunk = resp.read(1 << 16)
                    if not chunk:
                        break
                    f.write(chunk)
            tmp.rename(dest)
            (MODEL_DIR / "face_emotion_labels.txt").write_text("\n".join(labels))
            logger.info(f"Model saved to {dest}")
            return dest, labels
        except Exception as e:
            logger.warning(f"Download failed ({url}): {e}")

    logger.warning("All model sources failed — geometry-only mode.")
    return None


def _load_cached_labels() -> Optional[List[str]]:
    p = MODEL_DIR / "face_emotion_labels.txt"
    if p.exists():
        return [l.strip() for l in p.read_text().splitlines() if l.strip()]
    return None


# ── Preprocessing ─────────────────────────────────────────────────────────────

def _preprocess(face_bgr) -> "np.ndarray":
    import numpy as np
    h, w = face_bgr.shape[:2]
    s = min(h, w)
    y0, x0 = (h - s) // 2, (w - s) // 2
    cropped = face_bgr[y0:y0+s, x0:x0+s]
    resized = cv2.resize(cropped, MODEL_INPUT_SIZE)
    # FERPlus expects raw grayscale pixel values (0-255), shape (1, 1, 64, 64)
    gray = cv2.cvtColor(resized, cv2.COLOR_BGR2GRAY).astype("float32")
    return gray[None, None]  # shape: (1, 1, 64, 64)


def _softmax(x) -> "np.ndarray":
    import numpy as np
    e = np.exp(x - np.max(x))
    return e / e.sum()


# ── ONNX wrapper ──────────────────────────────────────────────────────────────

class ONNXEmotionModel:
    def __init__(self, path: Path, labels: List[str]):
        import onnxruntime as ort
        self.labels = [l.lower().strip() for l in labels]
        self.session = ort.InferenceSession(
            str(path), providers=["CPUExecutionProvider"]
        )
        self.input_name = self.session.get_inputs()[0].name
        logger.info(f"ONNX model ready: {path.name}  labels={self.labels}")

    def predict(self, face_bgr) -> Optional[Dict[str, float]]:
        try:
            inp = _preprocess(face_bgr)
            probs = _softmax(self.session.run(None, {self.input_name: inp})[0][0])

            scores = {k: 0.0 for k in ["joy","sadness","fear","disgust","anger","surprise"]}
            neutral = 0.0
            for i, label in enumerate(self.labels):
                field = LABEL_TO_FIELD.get(label)
                if field == "neutral":
                    neutral = float(probs[i])
                elif field in scores:
                    scores[field] += float(probs[i])

            # Neutral → small joy baseline (face is just relaxed)
            if neutral > 0.0:
                scores["joy"] = max(scores["joy"], neutral * 0.25)

            scores["_confidence"] = min(0.95, max(0.30, 1.0 - neutral * 0.60))
            return scores
        except Exception as e:
            logger.warning(f"ONNX inference error: {e}")
            return None


# ── Temporal smoother ─────────────────────────────────────────────────────────

class EmotionSmoother:
    KEYS = ["joy","sadness","fear","disgust","anger","surprise"]

    def __init__(self, alpha: float = EMA_ALPHA, hysteresis: float = HYSTERESIS_MARGIN):
        self.alpha = alpha
        self.hysteresis = hysteresis
        self._s = {k: 0.0 for k in self.KEYS}
        self._dominant: Optional[str] = None
        self._init = False

    def update(self, raw: Dict[str, float]) -> Dict[str, float]:
        if not self._init:
            self._s = {k: raw.get(k, 0.0) for k in self.KEYS}
            self._init = True
            self._dominant = max(self._s, key=self._s.get)
            return dict(self._s)

        for k in self.KEYS:
            self._s[k] = self.alpha * raw.get(k, 0.0) + (1 - self.alpha) * self._s[k]

        best = max(self._s, key=self._s.get)
        if self._dominant is None:
            self._dominant = best
        elif best != self._dominant:
            if self._s[best] - self._s[self._dominant] >= self.hysteresis:
                self._dominant = best

        return dict(self._s)

    def reset(self):
        self._s = {k: 0.0 for k in self.KEYS}
        self._dominant = None
        self._init = False


# ── Main detector ─────────────────────────────────────────────────────────────

class FaceEmotionDetector:

    def __init__(self, camera_index: int = 0, auto_download_model: bool = True):
        self.camera_index = camera_index
        self._cap = None
        self._face_mesh = None
        self._mp_available = False
        self._last_vector = None
        self._model: Optional[ONNXEmotionModel] = None
        self._smoother = EmotionSmoother()

        # Geometry calibration state
        self._calibration_frames = []
        self._calibrated = False
        self._calibration_target = 30
        self._baseline_ear = self._baseline_mar = None
        self._baseline_brow_u = self._baseline_smile = None

        self._sample_interval_s = float(FACE_SAMPLE_INTERVAL_S)
        self._last_sample_ts = 0.0

        self._init_camera()
        self._init_mediapipe()
        self._init_model(auto_download_model)

    # ── Init ──────────────────────────────────────────────────────────────────

    def _init_camera(self):
        self._cap = cv2.VideoCapture(self.camera_index, cv2.CAP_DSHOW)
        if not self._cap.isOpened():
            self._cap = cv2.VideoCapture(self.camera_index)
        if self._cap.isOpened():
            self._cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)
            self._cap.set(cv2.CAP_PROP_FPS, 30)
            logger.info(f"Camera {self.camera_index} opened.")
        else:
            logger.warning(f"Camera {self.camera_index} unavailable.")

    def _init_mediapipe(self):
        try:
            from mediapipe import solutions
            self._mp_face_mesh = solutions.face_mesh
            self._face_mesh = self._mp_face_mesh.FaceMesh(
                static_image_mode=False, max_num_faces=1,
                refine_landmarks=True,
                min_detection_confidence=0.5, min_tracking_confidence=0.5,
            )
            self._mp_available = True
            logger.info("MediaPipe FaceMesh loaded.")
        except ImportError:
            logger.warning("MediaPipe not installed.")

    def _init_model(self, auto_download: bool):
        if MODEL_PATH.exists():
            labels = _load_cached_labels()
            if labels:
                try:
                    self._model = ONNXEmotionModel(MODEL_PATH, labels)
                    return
                except Exception as e:
                    logger.warning(f"Cached model load failed: {e} — re-downloading.")
                    MODEL_PATH.unlink(missing_ok=True)

        if auto_download:
            result = _download_model()
            if result:
                try:
                    self._model = ONNXEmotionModel(result[0], result[1])
                except Exception as e:
                    logger.warning(f"Post-download model init failed: {e}")
        else:
            logger.info("auto_download=False — geometry-only.")

    # ── Geometry layer ────────────────────────────────────────────────────────

    def _ear(self, lm, idx) -> float:
        p = [lm[i] for i in idx]
        return (_dist(p[1],p[5]) + _dist(p[2],p[4])) / (2.0*_dist(p[0],p[3]) + 1e-6)

    def _mar(self, lm) -> float:
        return _dist(lm[13],lm[14]) / (_dist(lm[61],lm[291]) + 1e-6)

    def _smile(self, lm) -> float:
        mid_y = (lm[61].y + lm[291].y) / 2
        # In MediaPipe, Y increases downward. Mouth corners rise (lower Y) when smiling,
        # so (mid_y - lm[13].y) is positive for a smile.
        return max(-1.0, min(1.0, (mid_y - lm[13].y) * 20))

    def _brow_raise(self, lm) -> float:
        return max(0.0, min(1.0, ((lm[159].y - lm[105].y + lm[386].y - lm[334].y) / 2) * 12))

    def _brow_furrow(self, lm) -> float:
        return max(0.0, min(1.0, 1.0 - _dist(lm[107], lm[336]) / 0.10))

    def _calibrate(self, ear, mar, brow_u, smile):
        if self._calibrated:
            return
        self._calibration_frames.append((ear, mar, brow_u, smile))
        if len(self._calibration_frames) >= self._calibration_target:
            ears, mars, brows, smiles = zip(*self._calibration_frames)
            self._baseline_ear    = sum(ears)   / len(ears)
            self._baseline_mar    = sum(mars)   / len(mars)
            self._baseline_brow_u = sum(brows)  / len(brows)
            self._baseline_smile  = sum(smiles) / len(smiles)
            self._calibrated = True
            print(f"\n[FaceDetector] Calibrated EAR:{self._baseline_ear:.3f} "
                  f"MAR:{self._baseline_mar:.3f}")

    def _geometry_scores(self, lm) -> Optional[Dict[str, float]]:
        ear    = (self._ear(lm,[33,160,158,133,153,144]) + self._ear(lm,[362,385,387,263,373,380])) / 2
        mar    = self._mar(lm)
        smile  = self._smile(lm)
        brow_u = self._brow_raise(lm)
        furrow = self._brow_furrow(lm)

        self._calibrate(ear, mar, brow_u, smile)
        if not self._calibrated:
            return None

        ed = ear    - self._baseline_ear
        md = mar    - self._baseline_mar
        bd = brow_u - self._baseline_brow_u

        wide_eyes  = max(0.0, min(1.0,  ed / 0.08))
        open_mouth = max(0.0, min(1.0,  md / 0.15))
        brow_raise = max(0.0, min(1.0,  bd / 0.15))
        brow_low   = max(0.0, min(1.0, -bd / 0.10))
        squint     = max(0.0, min(1.0, -ed / 0.05))
        relaxed    = 1.0 - furrow

        sd = smile - (self._baseline_smile or 0.0)
        smile_gate = max(0.0, sd - max(0.0, -sd) * 0.40)
        frown      = max(0.0, -sd)

        joy      = smile_gate * 0.88 + max(0.0, squint-0.30)*0.10 + relaxed*0.06
        if smile_gate < 0.10: joy *= 0.30
        sadness  = frown*0.60 + max(0.0, brow_raise - furrow*0.5)*0.20 + (1-wide_eyes)*0.20
        fear     = wide_eyes*0.40 + brow_raise*furrow*0.35 + open_mouth*0.25
        surprise = wide_eyes*0.35 + open_mouth*0.40 + relaxed*0.25

        # Anger: needs brow involvement
        ab = brow_low*0.45 + furrow*0.30 + squint*0.25
        if smile_gate >= 0.25: ab *= (1 - smile_gate*0.15)
        anger = max(0.0, min(1.0, ab)) if (brow_low >= 0.15 and (furrow >= 0.20 or squint >= 0.20)) else 0.0

        db = frown*0.45 + brow_low*0.35 + squint*0.20
        if smile_gate >= 0.25: db *= (1 - smile_gate*0.12)
        disgust = max(0.0, min(1.0, db))

        if smile_gate >= 0.14:
            joy = max(joy, 0.60 + min(0.35, smile_gate))
            sadness *= 0.25; fear *= 0.30; disgust *= 0.30; surprise *= 0.30; anger = 0.0

        if smile_gate < 0.15 and max(sadness, fear, anger, disgust) > 0.35:
            joy *= 0.45

        return {k: min(1.0, v) for k, v in
                [("joy",joy),("sadness",sadness),("fear",fear),
                 ("disgust",disgust),("anger",anger),("surprise",surprise)]}

    # ── Face ROI ──────────────────────────────────────────────────────────────

    def _face_roi(self, frame, lm):
        h, w = frame.shape[:2]
        xs = [int(l.x*w) for l in lm]; ys = [int(l.y*h) for l in lm]
        x1 = max(0, min(xs)-20); x2 = min(w, max(xs)+20)
        y1 = max(0, min(ys)-20); y2 = min(h, max(ys)+20)
        roi = frame[y1:y2, x1:x2]
        return roi if roi.shape[0] >= 32 and roi.shape[1] >= 32 else None

    # ── Fusion ────────────────────────────────────────────────────────────────

    def _fuse(self, model: Optional[Dict], geo: Optional[Dict]) -> Tuple[Dict, float]:
        KEYS = ["joy","sadness","fear","disgust","anger","surprise"]
        if model is None and geo is None:
            return {k:0.0 for k in KEYS}, 0.0
        if model is None:
            return geo, 0.55
        if geo is None:
            c = model.get("_confidence", 0.70)
            return {k: model.get(k,0.0) for k in KEYS}, c

        mc = model.get("_confidence", 0.50)
        if   mc >= 0.45: mw, gw = 0.80, 0.20
        elif mc >= 0.25: mw, gw = 0.55, 0.45
        else:            mw, gw = 0.25, 0.75

        fused = {k: mw*model.get(k,0.0) + gw*geo.get(k,0.0) for k in KEYS}
        conf  = min(0.92, 0.50 + mc*0.40 + max(fused.values())*0.10)
        return fused, conf

    # ── Decay ─────────────────────────────────────────────────────────────────

    def _decay(self) -> EmotionVector:
        if not self._last_vector:
            return EmotionVector(confidence=0.08, source="face_no_landmarks")
        d = EmotionVector(source="face_no_landmarks")
        for k in ["joy","sadness","fear","disgust","anger","surprise"]:
            setattr(d, k, getattr(self._last_vector, k) * 0.75)
        d.confidence = max(0.05, self._last_vector.confidence * 0.35)
        self._last_vector = d.clamp()
        return self._last_vector

    # ── Public API ────────────────────────────────────────────────────────────

    def get_frame(self):
        if self._cap and self._cap.isOpened():
            ret, frame = self._cap.read()
            return frame if ret else None
        return None

    def detect(self, frame=None) -> EmotionVector:
        if frame is None:
            frame = self.get_frame()
        if frame is None:
            return EmotionVector(confidence=0.0, source="face")
        if not self._mp_available:
            return EmotionVector(confidence=0.0, source="face_unavailable")

        if self._calibrated and self._last_vector and self._sample_interval_s > 0:
            if (time.time() - self._last_sample_ts) < self._sample_interval_s:
                return self._last_vector

        rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        rgb.flags.writeable = False
        try:
            results = self._face_mesh.process(rgb)
            rgb.flags.writeable = True
            if not results.multi_face_landmarks:
                return self._decay()

            lm = results.multi_face_landmarks[0].landmark

            geo = self._geometry_scores(lm)
            if not self._calibrated:
                return EmotionVector(source="face_calibrating", confidence=0.0)

            model_out = None
            if self._model:
                roi = self._face_roi(frame, lm)
                if roi is not None:
                    model_out = self._model.predict(roi)

            raw, confidence = self._fuse(model_out, geo)
            smoothed = self._smoother.update(raw)

            src = "face_hybrid" if model_out is not None else "face_geometry"
            vector = EmotionVector(
                joy=smoothed["joy"], sadness=smoothed["sadness"],
                fear=smoothed["fear"], disgust=smoothed["disgust"],
                anger=smoothed["anger"], surprise=smoothed["surprise"],
                confidence=confidence, source=src,
            ).clamp()

            self._last_vector    = vector
            self._last_sample_ts = time.time()
            return vector

        except Exception as e:
            logger.warning(f"detect() error: {e}")
            return self._last_vector or EmotionVector(confidence=0.0, source="face")

    @property
    def model_loaded(self) -> bool:
        return self._model is not None

    @property
    def calibrated(self) -> bool:
        return self._calibrated

    def release(self):
        if self._cap:      self._cap.release()
        if self._face_mesh: self._face_mesh.close()
        logger.info("FaceDetector released.")


# ── Quick test ────────────────────────────────────────────────────────────────

if __name__ == "__main__":
    print("Face Emotion Detector v5 (ONNX + geometry hybrid)")
    print("Hold NEUTRAL for 30 frames calibration, then express freely.")
    print("Press 'q' to quit.\n")

    det = FaceEmotionDetector(camera_index=0, auto_download_model=True)
    COLORS = {"joy":(0,220,100),"sadness":(255,100,50),"fear":(0,100,255),
              "disgust":(0,180,0),"anger":(0,0,255),"surprise":(255,220,0)}

    while True:
        frame = det.get_frame()
        if frame is None:
            print("No frame."); break

        v   = det.detect(frame=frame)
        em  = v.to_dict()
        dom, dv = max(em.items(), key=lambda x: x[1])

        if not det.calibrated:
            n = len(det._calibration_frames)
            print(f"\rCalibrating {n}/30 — hold neutral", end="", flush=True)
            cv2.putText(frame, f"Calibrating {n}/30", (10,35),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.8, (0,200,255), 2)
        else:
            bar = " | ".join(f"{k[:3]}:{val:.2f}" for k, val in em.items())
            print(f"\r[{v.source.replace('face_','')}] {bar} → {dom.upper():<10}",
                  end="", flush=True)
            bx, by = 10, 10
            for emo, val in em.items():
                bw = int(val * 160)
                cv2.rectangle(frame,(bx,by),(bx+160,by+14),(40,40,40),-1)
                cv2.rectangle(frame,(bx,by),(bx+bw, by+14),COLORS.get(emo,(200,200,200)),-1)
                cv2.putText(frame,f"{emo[:3]}:{val:.2f}",(bx+165,by+11),
                            cv2.FONT_HERSHEY_SIMPLEX,0.38,(255,255,255),1)
                by += 18
            cv2.putText(frame,f">> {dom.upper()} ({dv:.2f})  [{v.source}]",
                        (10,frame.shape[0]-15),cv2.FONT_HERSHEY_SIMPLEX,0.65,(0,255,200),2)

        cv2.imshow("RIO Face Emotion v5", frame)
        if cv2.waitKey(1) & 0xFF == ord("q"):
            break

    det.release()
    cv2.destroyAllWindows()

"""
face_detector.py (v5 — hybrid learned model + landmark geometry)

Architecture:
  PRIMARY  : ONNX emotion model (MobileNet fine-tuned on RAF-DB / AffectNet)
             → stable, generalises across glasses/lighting/skin tone
  SECONDARY: MediaPipe FaceMesh landmark geometry (v4 rules)
             → personal-baseline calibrated, no model needed, used as blend/fallback

Fusion:
  model_confidence >= 0.45  →  80% model  / 20% geometry
  model_confidence  0.25–0.45 → 55% model  / 45% geometry
  model_confidence  < 0.25  →  25% model  / 75% geometry
  model unavailable          → 100% geometry

Temporal smoothing:
  EMA (alpha=0.35) applied per-frame.
  Hysteresis (margin=0.12): dominant label only switches when new leader
  exceeds current leader by 0.12 — prevents rapid flicker.

Model:
  Downloaded on first run from Hugging Face Hub (~12 MB ONNX).
  Cached at ~/.rio_models/face_emotion.onnx
  Falls back gracefully to geometry-only if download fails.
  Requires: pip install huggingface_hub onnxruntime
"""

import cv2
import logging
import math
import time
import sys
from pathlib import Path
from typing import Optional, List, Dict, Tuple

if __name__ == "__main__":
    sys.path.insert(0, str(Path(__file__).parent.parent))

from perception.emotion_fusion import EmotionVector

try:
    from config import FACE_SAMPLE_INTERVAL_S
except Exception:
    FACE_SAMPLE_INTERVAL_S = 3.0

logger = logging.getLogger("FaceDetector")

# ── Model config ──────────────────────────────────────────────────────────────
MODEL_DIR  = Path(__file__).parent / "rio_models"
MODEL_PATH = MODEL_DIR / "face_emotion.onnx"

HF_SOURCES = [
    (
        "onnxmodelzoo/emotion-ferplus-8",
        "model/emotion-ferplus-8.onnx",
        ["neutral", "happiness", "surprise", "sadness", "anger", "disgust", "fear", "contempt"],
    ),
]

LABEL_TO_FIELD: Dict[str, str] = {
    "happiness": "joy",   "happy": "joy",      "joy": "joy",
    "sadness":   "sadness", "sad": "sadness",
    "anger":     "anger",   "angry": "anger",
    "fear":      "fear",    "fearful": "fear",
    "surprise":  "surprise","surprised": "surprise",
    "disgust":   "disgust", "disgusted": "disgust", "contempt": "disgust",
    "neutral":   "neutral", "calm": "neutral",
}

MODEL_INPUT_SIZE = (64, 64)   # emotion-ferplus-8 expects 64×64 grayscale

# ── Smoothing config ──────────────────────────────────────────────────────────

EMA_ALPHA         = 0.35
HYSTERESIS_MARGIN = 0.12

# ── Face score calibration ───────────────────────────────────────────────────

SADNESS_GAIN   = 1.35
SADNESS_OFFSET = 0.02


def _apply_face_biases(scores: Dict[str, float]) -> Dict[str, float]:
    sad = scores.get("sadness", 0.0)
    scores["sadness"] = min(1.0, sad * SADNESS_GAIN + SADNESS_OFFSET)
    return scores


# ── Geometry helper ───────────────────────────────────────────────────────────

def _dist(p1, p2) -> float:
    return math.sqrt((p1.x - p2.x) ** 2 + (p1.y - p2.y) ** 2)


# ── Model downloader ──────────────────────────────────────────────────────────

def _download_model() -> Optional[Tuple[Path, List[str]]]:
    import urllib.request

    MODEL_DIR.mkdir(parents=True, exist_ok=True)

    for url, labels in MODEL_URLS:
        try:
            logger.info(f"Downloading model from {url} ...")
            dest = MODEL_DIR / "face_emotion.onnx"
            tmp  = MODEL_DIR / "face_emotion.onnx.tmp"
            req = urllib.request.Request(url, headers={"User-Agent": "rio-face-detector/1.0"})
            with urllib.request.urlopen(req, timeout=120) as resp, open(tmp, "wb") as f:
                while True:
                    chunk = resp.read(1 << 16)
                    if not chunk:
                        break
                    f.write(chunk)
            tmp.rename(dest)
            (MODEL_DIR / "face_emotion_labels.txt").write_text("\n".join(labels))
            logger.info(f"Model saved to {dest}")
            return dest, labels
        except Exception as e:
            logger.warning(f"Download failed ({url}): {e}")

    logger.warning("All model sources failed — geometry-only mode.")
    return None


def _load_cached_labels() -> Optional[List[str]]:
    p = MODEL_DIR / "face_emotion_labels.txt"
    if p.exists():
        return [l.strip() for l in p.read_text().splitlines() if l.strip()]
    return None


# ── Preprocessing ─────────────────────────────────────────────────────────────

def _preprocess(face_bgr) -> "np.ndarray":
    import numpy as np
    h, w = face_bgr.shape[:2]
    s = min(h, w)
    y0, x0 = (h - s) // 2, (w - s) // 2
    cropped = face_bgr[y0:y0+s, x0:x0+s]
    resized = cv2.resize(cropped, MODEL_INPUT_SIZE)
    # FERPlus expects raw grayscale pixel values (0-255), shape (1, 1, 64, 64)
    gray = cv2.cvtColor(resized, cv2.COLOR_BGR2GRAY).astype("float32")
    return gray[None, None]  # shape: (1, 1, 64, 64)


def _softmax(x) -> "np.ndarray":
    import numpy as np
    e = np.exp(x - np.max(x))
    return e / e.sum()


# ── ONNX wrapper ──────────────────────────────────────────────────────────────

class ONNXEmotionModel:
    def __init__(self, path: Path, labels: List[str]):
        import onnxruntime as ort
        self.labels = [l.lower().strip() for l in labels]
        self.session = ort.InferenceSession(
            str(path), providers=["CPUExecutionProvider"]
        )
        self.input_name = self.session.get_inputs()[0].name
        logger.info(f"ONNX model ready: {path.name}  labels={self.labels}")

    def predict(self, face_bgr) -> Optional[Dict[str, float]]:
        try:
            inp = _preprocess(face_bgr)
            probs = _softmax(self.session.run(None, {self.input_name: inp})[0][0])

            scores = {k: 0.0 for k in ["joy","sadness","fear","disgust","anger","surprise"]}
            neutral = 0.0
            for i, label in enumerate(self.labels):
                field = LABEL_TO_FIELD.get(label)
                if field == "neutral":
                    neutral = float(probs[i])
                elif field in scores:
                    scores[field] += float(probs[i])

            # Neutral → small joy baseline (face is just relaxed)
            if neutral > 0.0:
                scores["joy"] = max(scores["joy"], neutral * 0.25)

            scores["_confidence"] = min(0.95, max(0.30, 1.0 - neutral * 0.60))
            return scores
        except Exception as e:
            logger.warning(f"ONNX inference error: {e}")
            return None


# ── Temporal smoother ─────────────────────────────────────────────────────────

class EmotionSmoother:
    KEYS = ["joy","sadness","fear","disgust","anger","surprise"]

    def __init__(self, alpha: float = EMA_ALPHA, hysteresis: float = HYSTERESIS_MARGIN):
        self.alpha = alpha
        self.hysteresis = hysteresis
        self._s = {k: 0.0 for k in self.KEYS}
        self._dominant: Optional[str] = None
        self._init = False

    def update(self, raw: Dict[str, float]) -> Dict[str, float]:
        if not self._init:
            self._s = {k: raw.get(k, 0.0) for k in self.KEYS}
            self._init = True
            self._dominant = max(self._s, key=self._s.get)
            return dict(self._s)

        for k in self.KEYS:
            self._s[k] = self.alpha * raw.get(k, 0.0) + (1 - self.alpha) * self._s[k]

        best = max(self._s, key=self._s.get)
        if self._dominant is None:
            self._dominant = best
        elif best != self._dominant:
            if self._s[best] - self._s[self._dominant] >= self.hysteresis:
                self._dominant = best

        return dict(self._s)

    def reset(self):
        self._s = {k: 0.0 for k in self.KEYS}
        self._dominant = None
        self._init = False


# ── Main detector ─────────────────────────────────────────────────────────────

class FaceEmotionDetector:

    def __init__(self, camera_index: int = 0, auto_download_model: bool = True):
        self.camera_index = camera_index
        self._cap = None
        self._face_mesh = None
        self._mp_available = False
        self._last_vector = None
        self._model: Optional[ONNXEmotionModel] = None
        self._smoother = EmotionSmoother()

        # Geometry calibration state
        self._calibration_frames = []
        self._calibrated = False
        self._calibration_target = 30
        self._baseline_ear = self._baseline_mar = None
        self._baseline_brow_u = self._baseline_smile = None

        self._sample_interval_s = float(FACE_SAMPLE_INTERVAL_S)
        self._last_sample_ts = 0.0

        self._init_camera()
        self._init_mediapipe()
        self._init_model(auto_download_model)

    # ── Init ──────────────────────────────────────────────────────────────────

    def _init_camera(self):
        self._cap = cv2.VideoCapture(self.camera_index, cv2.CAP_DSHOW)
        if not self._cap.isOpened():
            self._cap = cv2.VideoCapture(self.camera_index)
        if self._cap.isOpened():
            self._cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)
            self._cap.set(cv2.CAP_PROP_FPS, 30)
            logger.info(f"Camera {self.camera_index} opened.")
        else:
            logger.warning(f"Camera {self.camera_index} unavailable.")

    def _init_mediapipe(self):
        try:
            from mediapipe import solutions
            self._mp_face_mesh = solutions.face_mesh
            self._face_mesh = self._mp_face_mesh.FaceMesh(
                static_image_mode=False, max_num_faces=1,
                refine_landmarks=True,
                min_detection_confidence=0.5, min_tracking_confidence=0.5,
            )
            self._mp_available = True
            logger.info("MediaPipe FaceMesh loaded.")
        except ImportError:
            logger.warning("MediaPipe not installed.")

    def _init_model(self, auto_download: bool):
        if MODEL_PATH.exists():
            labels = _load_cached_labels()
            if labels:
                try:
                    self._model = ONNXEmotionModel(MODEL_PATH, labels)
                    return
                except Exception as e:
                    logger.warning(f"Cached model load failed: {e} — re-downloading.")
                    MODEL_PATH.unlink(missing_ok=True)

        if auto_download:
            result = _download_model()
            if result:
                try:
                    self._model = ONNXEmotionModel(result[0], result[1])
                except Exception as e:
                    logger.warning(f"Post-download model init failed: {e}")
        else:
            logger.info("auto_download=False — geometry-only.")

    # ── Geometry layer ────────────────────────────────────────────────────────

    def _ear(self, lm, idx) -> float:
        p = [lm[i] for i in idx]
        return (_dist(p[1],p[5]) + _dist(p[2],p[4])) / (2.0*_dist(p[0],p[3]) + 1e-6)

    def _mar(self, lm) -> float:
        return _dist(lm[13],lm[14]) / (_dist(lm[61],lm[291]) + 1e-6)

    def _smile(self, lm) -> float:
        mid_y = (lm[61].y + lm[291].y) / 2
        # In MediaPipe, Y increases downward. Mouth corners rise (lower Y) when smiling,
        # so (mid_y - lm[13].y) is positive for a smile.
        return max(-1.0, min(1.0, (mid_y - lm[13].y) * 20))

    def _brow_raise(self, lm) -> float:
        return max(0.0, min(1.0, ((lm[159].y - lm[105].y + lm[386].y - lm[334].y) / 2) * 12))

    def _brow_furrow(self, lm) -> float:
        return max(0.0, min(1.0, 1.0 - _dist(lm[107], lm[336]) / 0.10))

    def _calibrate(self, ear, mar, brow_u, smile):
        if self._calibrated:
            return
        self._calibration_frames.append((ear, mar, brow_u, smile))
        if len(self._calibration_frames) >= self._calibration_target:
            ears, mars, brows, smiles = zip(*self._calibration_frames)
            self._baseline_ear    = sum(ears)   / len(ears)
            self._baseline_mar    = sum(mars)   / len(mars)
            self._baseline_brow_u = sum(brows)  / len(brows)
            self._baseline_smile  = sum(smiles) / len(smiles)
            self._calibrated = True
            print(f"\n[FaceDetector] Calibrated EAR:{self._baseline_ear:.3f} "
                  f"MAR:{self._baseline_mar:.3f}")

    def _geometry_scores(self, lm) -> Optional[Dict[str, float]]:
        ear    = (self._ear(lm,[33,160,158,133,153,144]) + self._ear(lm,[362,385,387,263,373,380])) / 2
        mar    = self._mar(lm)
        smile  = self._smile(lm)
        brow_u = self._brow_raise(lm)
        furrow = self._brow_furrow(lm)

        self._calibrate(ear, mar, brow_u, smile)
        if not self._calibrated:
            return None

        ed = ear    - self._baseline_ear
        md = mar    - self._baseline_mar
        bd = brow_u - self._baseline_brow_u

        wide_eyes  = max(0.0, min(1.0,  ed / 0.08))
        open_mouth = max(0.0, min(1.0,  md / 0.15))
        brow_raise = max(0.0, min(1.0,  bd / 0.15))
        brow_low   = max(0.0, min(1.0, -bd / 0.10))
        squint     = max(0.0, min(1.0, -ed / 0.05))
        relaxed    = 1.0 - furrow

        sd = smile - (self._baseline_smile or 0.0)
        smile_gate = max(0.0, sd - max(0.0, -sd) * 0.40)
        frown      = max(0.0, -sd)

        joy      = smile_gate * 0.88 + max(0.0, squint-0.30)*0.10 + relaxed*0.06
        if smile_gate < 0.10: joy *= 0.30
        sadness  = frown*0.60 + max(0.0, brow_raise - furrow*0.5)*0.20 + (1-wide_eyes)*0.20
        fear     = wide_eyes*0.40 + brow_raise*furrow*0.35 + open_mouth*0.25
        surprise = wide_eyes*0.35 + open_mouth*0.40 + relaxed*0.25

        # Anger: needs brow involvement
        ab = brow_low*0.45 + furrow*0.30 + squint*0.25
        if smile_gate >= 0.25: ab *= (1 - smile_gate*0.15)
        anger = max(0.0, min(1.0, ab)) if (brow_low >= 0.15 and (furrow >= 0.20 or squint >= 0.20)) else 0.0

        db = frown*0.45 + brow_low*0.35 + squint*0.20
        if smile_gate >= 0.25: db *= (1 - smile_gate*0.12)
        disgust = max(0.0, min(1.0, db))

        if smile_gate >= 0.14:
            joy = max(joy, 0.60 + min(0.35, smile_gate))
            sadness *= 0.25; fear *= 0.30; disgust *= 0.30; surprise *= 0.30; anger = 0.0

        if smile_gate < 0.15 and max(sadness, fear, anger, disgust) > 0.35:
            joy *= 0.45

        return {k: min(1.0, v) for k, v in
                [("joy",joy),("sadness",sadness),("fear",fear),
                 ("disgust",disgust),("anger",anger),("surprise",surprise)]}

    # ── Face ROI ──────────────────────────────────────────────────────────────

    def _face_roi(self, frame, lm):
        h, w = frame.shape[:2]
        xs = [int(l.x*w) for l in lm]; ys = [int(l.y*h) for l in lm]
        x1 = max(0, min(xs)-20); x2 = min(w, max(xs)+20)
        y1 = max(0, min(ys)-20); y2 = min(h, max(ys)+20)
        roi = frame[y1:y2, x1:x2]
        return roi if roi.shape[0] >= 32 and roi.shape[1] >= 32 else None

    # ── Fusion ────────────────────────────────────────────────────────────────

    def _fuse(self, model: Optional[Dict], geo: Optional[Dict]) -> Tuple[Dict, float]:
        KEYS = ["joy","sadness","fear","disgust","anger","surprise"]
        if model is None and geo is None:
            return {k:0.0 for k in KEYS}, 0.0
        if model is None:
            return geo, 0.55
        if geo is None:
            c = model.get("_confidence", 0.70)
            return {k: model.get(k,0.0) for k in KEYS}, c

        mc = model.get("_confidence", 0.50)
        if   mc >= 0.45: mw, gw = 0.80, 0.20
        elif mc >= 0.25: mw, gw = 0.55, 0.45
        else:            mw, gw = 0.25, 0.75

        fused = {k: mw*model.get(k,0.0) + gw*geo.get(k,0.0) for k in KEYS}
        conf  = min(0.92, 0.50 + mc*0.40 + max(fused.values())*0.10)
        return fused, conf

    # ── Decay ─────────────────────────────────────────────────────────────────

    def _decay(self) -> EmotionVector:
        if not self._last_vector:
            return EmotionVector(confidence=0.08, source="face_no_landmarks")
        d = EmotionVector(source="face_no_landmarks")
        for k in ["joy","sadness","fear","disgust","anger","surprise"]:
            setattr(d, k, getattr(self._last_vector, k) * 0.75)
        d.confidence = max(0.05, self._last_vector.confidence * 0.35)
        self._last_vector = d.clamp()
        return self._last_vector

    # ── Public API ────────────────────────────────────────────────────────────

    def get_frame(self):
        if self._cap and self._cap.isOpened():
            ret, frame = self._cap.read()
            return frame if ret else None
        return None

    def detect(self, frame=None) -> EmotionVector:
        if frame is None:
            frame = self.get_frame()
        if frame is None:
            return EmotionVector(confidence=0.0, source="face")
        if not self._mp_available:
            return EmotionVector(confidence=0.0, source="face_unavailable")

        if self._calibrated and self._last_vector and self._sample_interval_s > 0:
            if (time.time() - self._last_sample_ts) < self._sample_interval_s:
                return self._last_vector

        rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        rgb.flags.writeable = False
        try:
            results = self._face_mesh.process(rgb)
            rgb.flags.writeable = True
            if not results.multi_face_landmarks:
                return self._decay()

            lm = results.multi_face_landmarks[0].landmark

            geo = self._geometry_scores(lm)
            if not self._calibrated:
                return EmotionVector(source="face_calibrating", confidence=0.0)

            model_out = None
            if self._model:
                roi = self._face_roi(frame, lm)
                if roi is not None:
                    model_out = self._model.predict(roi)

            raw, confidence = self._fuse(model_out, geo)
            raw = _apply_face_biases(raw)
            smoothed = self._smoother.update(raw)

            src = "face_hybrid" if model_out is not None else "face_geometry"
            vector = EmotionVector(
                joy=smoothed["joy"], sadness=smoothed["sadness"],
                fear=smoothed["fear"], disgust=smoothed["disgust"],
                anger=smoothed["anger"], surprise=smoothed["surprise"],
                confidence=confidence, source=src,
            ).clamp()

            self._last_vector    = vector
            self._last_sample_ts = time.time()
            return vector

        except Exception as e:
            logger.warning(f"detect() error: {e}")
            return self._last_vector or EmotionVector(confidence=0.0, source="face")

    @property
    def model_loaded(self) -> bool:
        return self._model is not None

    @property
    def calibrated(self) -> bool:
        return self._calibrated

    def release(self):
        if self._cap:      self._cap.release()
        if self._face_mesh: self._face_mesh.close()
        logger.info("FaceDetector released.")


# ── Quick test ────────────────────────────────────────────────────────────────

if __name__ == "__main__":
    print("Face Emotion Detector v5 (ONNX + geometry hybrid)")
    print("Hold NEUTRAL for 30 frames calibration, then express freely.")
    print("Press 'q' to quit.\n")

    det = FaceEmotionDetector(camera_index=0, auto_download_model=True)
    COLORS = {"joy":(0,220,100),"sadness":(255,100,50),"fear":(0,100,255),
              "disgust":(0,180,0),"anger":(0,0,255),"surprise":(255,220,0)}

    while True:
        frame = det.get_frame()
        if frame is None:
            print("No frame."); break

        v   = det.detect(frame=frame)
        em  = v.to_dict()
        dom, dv = max(em.items(), key=lambda x: x[1])

        if not det.calibrated:
            n = len(det._calibration_frames)
            print(f"\rCalibrating {n}/30 — hold neutral", end="", flush=True)
            cv2.putText(frame, f"Calibrating {n}/30", (10,35),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.8, (0,200,255), 2)
        else:
            bar = " | ".join(f"{k[:3]}:{val:.2f}" for k, val in em.items())
            print(f"\r[{v.source.replace('face_','')}] {bar} → {dom.upper():<10}",
                  end="", flush=True)
            bx, by = 10, 10
            for emo, val in em.items():
                bw = int(val * 160)
                cv2.rectangle(frame,(bx,by),(bx+160,by+14),(40,40,40),-1)
                cv2.rectangle(frame,(bx,by),(bx+bw, by+14),COLORS.get(emo,(200,200,200)),-1)
                cv2.putText(frame,f"{emo[:3]}:{val:.2f}",(bx+165,by+11),
                            cv2.FONT_HERSHEY_SIMPLEX,0.38,(255,255,255),1)
                by += 18
            cv2.putText(frame,f">> {dom.upper()} ({dv:.2f})  [{v.source}]",
                        (10,frame.shape[0]-15),cv2.FONT_HERSHEY_SIMPLEX,0.65,(0,255,200),2)

        cv2.imshow("RIO Face Emotion v5", frame)
        if cv2.waitKey(1) & 0xFF == ord("q"):
            break

    det.release()
    cv2.destroyAllWindows()

// mic_bridge.js
// Browser microphone → WebSocket → Python pipeline
// Sends: transcript text + raw audio chunks
// Auto-reconnects if WebSocket drops

(function() {
  const WS_URL = "ws://0.0.0.0:8765";
  const micBtn  = document.getElementById("micBtn");
  const micDot  = document.getElementById("micDot");

  let ws         = null;
  let recognition = null;
  let mediaRecorder = null;
  let isListening = false;

  // ── WebSocket is managed by app.js ───────────────────────────────────
  // mic_bridge.js just uses the same socket via a shared getter
  // We wait for app.js to create window._rioWS, or create our own ref
  function getWS() {
    // app.js sets window._rioWS after connect
    return window._rioWS || null;
  }

  // ── Speech Recognition (transcript) ──────────────────────────────────
  function initRecognition() {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      console.warn("[MicBridge] SpeechRecognition not supported in this browser.");
      if (micBtn) micBtn.title = "Voice not supported — use text input";
      return null;
    }

    const rec = new SpeechRecognition();
    rec.continuous      = true;
    rec.interimResults  = true;
    rec.lang            = "en-IN";   // works for both English and Hindi

    rec.onresult = (event) => {
      let finalText = "";
      for (let i = event.resultIndex; i < event.results.length; i++) {
        if (event.results[i].isFinal) {
          finalText += event.results[i][0].transcript.trim();
        }
      }
      if (finalText) {
        console.log("[MicBridge] Final transcript:", finalText);
        sendTranscript(finalText);
      }
    };

    rec.onerror = (e) => {
      if (e.error !== "no-speech") {
        console.warn("[MicBridge] Recognition error:", e.error);
      }
    };

    rec.onend = () => {
      // Auto-restart if still supposed to be listening
      if (isListening) {
        setTimeout(() => { try { rec.start(); } catch(e) {} }, 300);
      }
    };

    return rec;
  }

  // ── Audio streaming (for voice emotion) ──────────────────────────────
  async function startAudioStream() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorder = new MediaRecorder(stream, { mimeType: "audio/webm" });

      mediaRecorder.ondataavailable = async (e) => {
        if (e.data.size === 0) return;
        const ws = getWS();
        if (!ws || ws.readyState !== WebSocket.OPEN) return;

        // Convert blob to base64 and send
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64 = reader.result.split(",")[1];
          ws.send(JSON.stringify({ type: "audio", data: base64 }));
        };
        reader.readAsDataURL(e.data);
      };

      // Send chunks every 1 second
      mediaRecorder.start(1000);
      console.log("[MicBridge] Audio stream started");
    } catch(e) {
      console.warn("[MicBridge] Mic access denied or unavailable:", e.message);
    }
  }

  function stopAudioStream() {
    if (mediaRecorder && mediaRecorder.state !== "inactive") {
      mediaRecorder.stop();
      mediaRecorder = null;
    }
  }

  // ── Send transcript via WebSocket ─────────────────────────────────────
  function sendTranscript(text) {
    const ws = getWS();
    if (!ws || ws.readyState !== WebSocket.OPEN) {
      console.warn("[MicBridge] WS not open, cannot send transcript");
      return;
    }
    ws.send(JSON.stringify({ type: "transcript", text }));
  }

  // ── Mic button toggle ─────────────────────────────────────────────────
  function startListening() {
    isListening = true;
    if (!recognition) recognition = initRecognition();
    if (recognition) {
      try { recognition.start(); } catch(e) {}
    }
    startAudioStream();
    if (micBtn) {
      micBtn.textContent = "";
      micBtn.title = "Listening... click to stop";
    }
  }

  function stopListening() {
    isListening = false;
    if (recognition) { try { recognition.stop(); } catch(e) {} }
    stopAudioStream();
    if (micBtn) {
      micBtn.textContent = "";
      micBtn.title = "Click to speak";
    }
  }

  if (micBtn) {
    micBtn.addEventListener("click", () => {
      isListening ? stopListening() : startListening();
    });
  }

  // ── Expose WS to app.js ───────────────────────────────────────────────
  // app.js should set window._rioWS = ws after connecting
  // We patch connect() timing by polling
  const _origConnect = window._rioConnect;

  // Auto-start listening once page loads (optional — remove if unwanted)
  // window.addEventListener("load", () => setTimeout(startListening, 2000));

  console.log("[MicBridge] Ready. Click  to start voice input.");
})();

// mic_bridge.js
// Browser microphone → WebSocket → Python pipeline
// Sends: transcript text + raw audio chunks
// Auto-reconnects if WebSocket drops

(function() {
  const WS_URL = "ws://0.0.0.0:8765";
  const micBtn  = document.getElementById("micBtn");
  const micDot  = document.getElementById("micDot");

  let ws         = null;
  let recognition = null;
  let mediaRecorder = null;
  let isListening = false;
  let audioContext = null;
  let audioProcessor = null;
  let audioSource = null;

  // ── WebSocket is managed by app.js ───────────────────────────────────
  // mic_bridge.js just uses the same socket via a shared getter
  // We wait for app.js to create window._rioWS, or create our own ref
  function getWS() {
    // app.js sets window._rioWS after connect
    return window._rioWS || null;
  }

  // ── Speech Recognition (transcript) ──────────────────────────────────
  function initRecognition() {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      console.warn("[MicBridge] SpeechRecognition not supported in this browser.");
      if (micBtn) micBtn.title = "Voice not supported — use text input";
      return null;
    }

    const rec = new SpeechRecognition();
    rec.continuous      = true;
    rec.interimResults  = true;
    rec.lang            = "en-IN";   // works for both English and Hindi

    rec.onresult = (event) => {
      let finalText = "";
      for (let i = event.resultIndex; i < event.results.length; i++) {
        if (event.results[i].isFinal) {
          finalText += event.results[i][0].transcript.trim();
        }
      }
      if (finalText) {
        console.log("[MicBridge] Final transcript:", finalText);
        sendTranscript(finalText);
      }
    };

    rec.onerror = (e) => {
      if (e.error !== "no-speech") {
        console.warn("[MicBridge] Recognition error:", e.error);
      }
    };

    rec.onend = () => {
      // Auto-restart if still supposed to be listening
      if (isListening) {
        setTimeout(() => { try { rec.start(); } catch(e) {} }, 300);
      }
    };

    return rec;
  }

  // ── Audio streaming (for voice emotion) ──────────────────────────────
  async function startAudioStream() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContext = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 16000 });
      audioSource = audioContext.createMediaStreamSource(stream);
      audioProcessor = audioContext.createScriptProcessor(4096, 1, 1);

      audioProcessor.onaudioprocess = (e) => {
        const ws = getWS();
        if (!ws || ws.readyState !== WebSocket.OPEN) return;

        const input = e.inputBuffer.getChannelData(0);
        const pcm16 = new Int16Array(input.length);
        for (let i = 0; i < input.length; i++) {
          const s = Math.max(-1, Math.min(1, input[i]));
          pcm16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
        }

        const bytes = new Uint8Array(pcm16.buffer);
        let binary = "";
        for (let i = 0; i < bytes.length; i++) {
          binary += String.fromCharCode(bytes[i]);
        }
        const base64 = btoa(binary);
        ws.send(JSON.stringify({ type: "audio", data: base64, sampleRate: 16000 }));
      };

      audioSource.connect(audioProcessor);
      audioProcessor.connect(audioContext.destination);
      console.log("[MicBridge] Audio stream started (PCM16)");
    } catch(e) {
      console.warn("[MicBridge] Mic access denied or unavailable:", e.message);
    }
  }

  function stopAudioStream() {
    if (audioProcessor) {
      audioProcessor.disconnect();
      audioProcessor = null;
    }
    if (audioSource) {
      audioSource.disconnect();
      audioSource = null;
    }
    if (audioContext) {
      audioContext.close();
      audioContext = null;
    }
  }

  // ── Send transcript via WebSocket ─────────────────────────────────────
  function sendTranscript(text) {
    const ws = getWS();
    if (!ws || ws.readyState !== WebSocket.OPEN) {
      console.warn("[MicBridge] WS not open, cannot send transcript");
      return;
    }
    ws.send(JSON.stringify({ type: "transcript", text }));
  }

  // ── Mic button toggle ─────────────────────────────────────────────────
  function startListening() {
    isListening = true;
    if (!recognition) recognition = initRecognition();
    if (recognition) {
      try { recognition.start(); } catch(e) {}
    }
    startAudioStream();
    if (micBtn) {
      micBtn.textContent = "";
      micBtn.title = "Listening... click to stop";
    }
  }

  function stopListening() {
    isListening = false;
    if (recognition) { try { recognition.stop(); } catch(e) {} }
    stopAudioStream();
    if (micBtn) {
      micBtn.textContent = "";
      micBtn.title = "Click to speak";
    }
  }

  if (micBtn) {
    micBtn.addEventListener("click", () => {
      isListening ? stopListening() : startListening();
    });
  }

  // ── Expose WS to app.js ───────────────────────────────────────────────
  // app.js should set window._rioWS = ws after connecting
  // We patch connect() timing by polling
  const _origConnect = window._rioConnect;

  // Auto-start listening once page loads (optional — remove if unwanted)
  // window.addEventListener("load", () => setTimeout(startListening, 2000));

  console.log("[MicBridge] Ready. Click  to start voice input.");
})();

""" Pipeline Manager — Orchestrates dialogue, servo, and feedback agents sequentially.
Flow: 1. DIALOGUE AGENT: Generates response & emotion/expression intent based on stimulus 2. SERVO AGENT: Applies emotion-specific servo poses from servo_controls/poses.json Uses smooth transitions and alive animation while TTS speaks 3. FEEDBACK AGENT: Assesses intervention effectiveness
The servo positions are dynamically applied based on the expression_intent (emotion) chosen by the dialogue agent, creating embodied emotional responses synchronized with the robot's speech. """
import logging from typing import Dict, Any
from cognition.agents.dialogue_agent import run_dialogue from cognition.agents.servo_agent import run_servo, resolve_emotion from cognition.agents.feedback_agent import run_feedback
logger = logging.getLogger(__name__)
NEGATIVE_EMOTIONS = {"sadness", "fear", "anger", "disgust"}
def _dominant_from_stimulus(stimulus: Dict[str, Any]) -> tuple[str, float]: emotions = stimulus.get("emotions") or {} if not emotions: return ("neutral", 0.0) dom, val = max(emotions.items(), key=lambda item: item[1]) return (str(dom), float(val))
def merge_tts_for_therapist(expression_intent: str, tts: Dict[str, Any]) -> Dict[str, float]: """ Blend LLM TTS hints with therapist-style baselines per facial expression. Sad: softer, slower. Anger: firm and measured (not loud/fast). Calm: steady, slightly slow. """ ex = (expression_intent or "calm").lower() baselines = { "sadness": {"pitch": 0.86, "speed": 0.84}, "anger": {"pitch": 0.90, "speed": 0.86}, "fear": {"pitch": 0.93, "speed": 0.88}, "joy": {"pitch": 1.05, "speed": 0.98}, "surprise": {"pitch": 1.04, "speed": 0.95}, "calm": {"pitch": 0.98, "speed": 0.90}, } base = baselines.get(ex, baselines["calm"]) lp = float(tts.get("pitch", base["pitch"])) ls = float(tts.get("speed", base["speed"])) p = 0.55 * base["pitch"] + 0.45 * lp s = 0.55 * base["speed"] + 0.45 * ls p = max(0.78, min(1.32, p)) s = max(0.82, min(1.12, s)) return {"pitch": p, "speed": s}
def _emotion_intensity_index(emotion: str, stimulus: Dict[str, Any]) -> int: resolved = resolve_emotion(emotion) value = float((stimulus.get("emotions") or {}).get(resolved, 0.0)) return max(0, min(4, int(round(value * 4))))
def run_pipeline( stimulus: Dict[str, Any], intervention_intent: str, user_transcript: str, memory_context: str, emotion_before: Dict[str, float], ) -> Dict[str, Any]: """ Run the full dialogue → servo → feedback pipeline sequentially.
Args: stimulus: StimulusObject.to_dict() (emotion vectors, metadata). intervention_intent: e.g., "deflect_sadness", "reinforce_joy". user_transcript: What the user just said. memory_context: Summary of recent interactions (plain text). emotion_before: Emotion vector before intervention.
Returns: Dict with response_text, expression_intent, tts_params, and feedback. """ dialogue_output = None servo_output = None feedback_output = None
# Step 1: Run dialogue agent try: dialogue_output = run_dialogue( stimulus=stimulus, intervention_intent=intervention_intent, user_transcript=user_transcript, memory_context=memory_context, ) logger.info(f"Dialogue: {dialogue_output['expression_intent']}") except Exception as e: logger.error(f"Dialogue agent failed: {e}", exc_info=True) if not (memory_context or "").strip(): dialogue_output = { "response_text": "Hello! I'm RIO. Welcome back. How has your day been so far?", "expression_intent": "calm", "tts_params": {"pitch": 1.0, "speed": 0.98}, } else: dialogue_output = { "response_text": "I'm here for you. What would feel a little easier right now?", "expression_intent": "calm", "tts_params": {"pitch": 0.98, "speed": 0.90}, }
# Mirror user emotion before uplifting when negative is strong dominant_user, dominant_value = _dominant_from_stimulus(stimulus) if dominant_user in NEGATIVE_EMOTIONS and dominant_value >= 0.20: dialogue_output["expression_intent"] = dominant_user
dialogue_output["tts_params"] = merge_tts_for_therapist( dialogue_output.get("expression_intent", "calm"), dialogue_output.get("tts_params") or {}, )
# Step 2: Run servo agent with emotion-based positions try: # expression_intent is the emotion from the dialogue agent servo_output = run_servo( emotion=dialogue_output["expression_intent"], speaking=True, # Robot is about to speak, so use alive animation transition=True, # Smooth transition between poses intensity=_emotion_intensity_index(dialogue_output["expression_intent"], stimulus), ) logger.info(f"Servo: {servo_output['action']} → {servo_output['resolved_emotion']}") except Exception as e: logger.error(f"Servo agent failed: {e}", exc_info=True) servo_output = {"action": "error", "emotion": dialogue_output.get("expression_intent", "unknown")}
# Step 3: Run feedback agent try: emotion_after = stimulus.get("emotions", {}) feedback_output = run_feedback(emotion_before, emotion_after) logger.info(f"Feedback: {feedback_output['note']}") except Exception as e: logger.error(f"Feedback agent failed: {e}", exc_info=True) feedback_output = {"improved": False, "delta": 0.0, "note": "error"}
# Step 4: Return final combined output return { "response_text": dialogue_output["response_text"], "expression_intent": dialogue_output["expression_intent"], "tts_params": dialogue_output["tts_params"], "feedback": feedback_output, }

""" Pipeline Manager — Orchestrates dialogue, servo, and feedback agents sequentially.
Flow: 1. DIALOGUE AGENT: Generates response & emotion/expression intent based on stimulus 2. SERVO AGENT: Applies emotion-specific servo poses from servo_controls/poses.json Uses smooth transitions and alive animation while TTS speaks 3. FEEDBACK AGENT: Assesses intervention effectiveness
The servo positions are dynamically applied based on the expression_intent (emotion) chosen by the dialogue agent, creating embodied emotional responses synchronized with the robot's speech. """
import logging from typing import Dict, Any
from cognition.agents.dialogue_agent import run_dialogue from cognition.agents.servo_agent import run_servo, resolve_emotion from cognition.agents.feedback_agent import run_feedback
logger = logging.getLogger(__name__)
NEGATIVE_EMOTIONS = {"sadness", "fear", "anger", "disgust"} SADNESS_KEYWORDS = { "sad", "sadness", "depressed", "down", "lonely", "alone", "hopeless", "empty", "cry", "grief", "tired", "exhausted", }
def _dominant_from_stimulus(stimulus: Dict[str, Any]) -> tuple[str, float]: emotions = stimulus.get("emotions") or {} if not emotions: return ("neutral", 0.0) dom, val = max(emotions.items(), key=lambda item: item[1]) return (str(dom), float(val))
def merge_tts_for_therapist(expression_intent: str, tts: Dict[str, Any]) -> Dict[str, float]: """ Blend LLM TTS hints with therapist-style baselines per facial expression. Sad: softer, slower. Anger: firm and measured (not loud/fast). Calm: steady, slightly slow. """ ex = (expression_intent or "calm").lower() baselines = { "sadness": {"pitch": 0.86, "speed": 0.84}, "anger": {"pitch": 0.90, "speed": 0.86}, "fear": {"pitch": 0.93, "speed": 0.88}, "joy": {"pitch": 1.05, "speed": 0.98}, "surprise": {"pitch": 1.04, "speed": 0.95}, "calm": {"pitch": 0.98, "speed": 0.90}, } base = baselines.get(ex, baselines["calm"]) lp = float(tts.get("pitch", base["pitch"])) ls = float(tts.get("speed", base["speed"])) p = 0.55 * base["pitch"] + 0.45 * lp s = 0.55 * base["speed"] + 0.45 * ls p = max(0.78, min(1.32, p)) s = max(0.82, min(1.12, s)) return {"pitch": p, "speed": s}
def _emotion_intensity_index(emotion: str, stimulus: Dict[str, Any]) -> int: resolved = resolve_emotion(emotion) value = float((stimulus.get("emotions") or {}).get(resolved, 0.0)) return max(0, min(4, int(round(value * 4))))
def _transcript_sadness_hint(text: str) -> bool: cleaned = (text or "").lower() return any(word in cleaned for word in SADNESS_KEYWORDS)
def run_pipeline( stimulus: Dict[str, Any], intervention_intent: str, user_transcript: str, memory_context: str, emotion_before: Dict[str, float], ) -> Dict[str, Any]: """ Run the full dialogue → servo → feedback pipeline sequentially.
Args: stimulus: StimulusObject.to_dict() (emotion vectors, metadata). intervention_intent: e.g., "deflect_sadness", "reinforce_joy". user_transcript: What the user just said. memory_context: Summary of recent interactions (plain text). emotion_before: Emotion vector before intervention.
Returns: Dict with response_text, expression_intent, tts_params, and feedback. """ dialogue_output = None servo_output = None feedback_output = None
# Step 1: Run dialogue agent try: dialogue_output = run_dialogue( stimulus=stimulus, intervention_intent=intervention_intent, user_transcript=user_transcript, memory_context=memory_context, ) logger.info(f"Dialogue: {dialogue_output['expression_intent']}") except Exception as e: logger.error(f"Dialogue agent failed: {e}", exc_info=True) if not (memory_context or "").strip(): dialogue_output = { "response_text": "Hello! I'm RIO. Welcome back. How has your day been so far?", "expression_intent": "calm", "tts_params": {"pitch": 1.0, "speed": 0.98}, } else: dialogue_output = { "response_text": "I'm here for you. What would feel a little easier right now?", "expression_intent": "calm", "tts_params": {"pitch": 0.98, "speed": 0.90}, }
# Mirror user emotion before uplifting when negative is strong dominant_user, dominant_value = _dominant_from_stimulus(stimulus) if dominant_user in NEGATIVE_EMOTIONS and dominant_value >= 0.20: dialogue_output["expression_intent"] = dominant_user elif _transcript_sadness_hint(user_transcript): dialogue_output["expression_intent"] = "sadness"
dialogue_output["tts_params"] = merge_tts_for_therapist( dialogue_output.get("expression_intent", "calm"), dialogue_output.get("tts_params") or {}, )
# Step 2: Run servo agent with emotion-based positions try: # expression_intent is the emotion from the dialogue agent servo_output = run_servo( emotion=dialogue_output["expression_intent"], speaking=True, # Robot is about to speak, so use alive animation transition=True, # Smooth transition between poses intensity=_emotion_intensity_index(dialogue_output["expression_intent"], stimulus), ) logger.info(f"Servo: {servo_output['action']} → {servo_output['resolved_emotion']}") except Exception as e: logger.error(f"Servo agent failed: {e}", exc_info=True) servo_output = {"action": "error", "emotion": dialogue_output.get("expression_intent", "unknown")}
# Step 3: Run feedback agent try: emotion_after = stimulus.get("emotions", {}) feedback_output = run_feedback(emotion_before, emotion_after) logger.info(f"Feedback: {feedback_output['note']}") except Exception as e: logger.error(f"Feedback agent failed: {e}", exc_info=True) feedback_output = {"improved": False, "delta": 0.0, "note": "error"}
# Step 4: Return final combined output return { "response_text": dialogue_output["response_text"], "expression_intent": dialogue_output["expression_intent"], "tts_params": dialogue_output["tts_params"], "feedback": feedback_output, }

"""
ws_server.py
------------
WebSocket server on port 8765.
Browser sends transcript → Python pipeline runs → response sent back to browser.

Messages FROM browser:
  {"type": "transcript", "text": "..."}
  {"type": "audio", "data": "<base64>"}   ← raw mic audio for voice emotion

Messages TO browser:
  {"type": "transcript_ack", "text": "..."}
  {"type": "rio_response", "text": "...", "expression": "calm"}
  {"type": "play_audio", "url": "/audio/response.mp3"}
  {"type": "emotion_update", "emotions": {...}}
"""

import asyncio
import base64
import json
import logging
import queue
import threading
from pathlib import Path
import numpy as np

import websockets

logger = logging.getLogger("ws_server")

# ── Shared state ──────────────────────────────────────────────────────────
_transcript_queue: queue.Queue = queue.Queue()
_response_queue:   queue.Queue = queue.Queue()   # main.py puts responses here
_connected_clients: set = set()
_loop: asyncio.AbstractEventLoop | None = None

# ── Public API (called from main.py) ─────────────────────────────────────

def get_latest_transcript() -> str | None:
    """Pop the latest transcript from the browser. Returns None if empty."""
    try:
        return _transcript_queue.get_nowait()
    except queue.Empty:
        return None


def send_response_to_browser(
    response_text: str,
    expression: str,
    audio_url: str,
    rio_state: dict | None = None,
    intervention_intent: dict | str | None = None,
    pipeline_feedback: dict | None = None,
) -> None:
    """
    Push a RIO response to all connected browser clients.
    Call this from main.py after the pipeline runs.
    """
    normalized_audio_url = audio_url if str(audio_url).startswith("/audio/") else "/audio/response.mp3"
    _response_queue.put({
        "response_text": response_text,
        "expression": expression,
        "audio_url": normalized_audio_url,
        "rio_state": rio_state or {},
        "intervention_intent": intervention_intent or {},
        "pipeline_feedback": pipeline_feedback or {},
    })
    # Wake up the async loop to flush the queue
    if _loop and not _loop.is_closed():
        _loop.call_soon_threadsafe(_flush_response_queue_sync)


def send_emotion_update(emotions: dict) -> None:
    """Push live emotion vector to browser (for details panel)."""
    _response_queue.put({"__type": "emotion_update", "emotions": emotions})
    if _loop and not _loop.is_closed():
        _loop.call_soon_threadsafe(_flush_response_queue_sync)


def _flush_response_queue_sync():
    """Schedules async flush from sync context."""
    if _loop:
        asyncio.ensure_future(_flush_response_queue(), loop=_loop)


# ── WebSocket handler ─────────────────────────────────────────────────────

async def _handler(websocket):
    _connected_clients.add(websocket)
    logger.info(f"[WS] Client connected. Total: {len(_connected_clients)}")
    try:
        async for raw in websocket:
            try:
                msg = json.loads(raw)
                await _handle_message(websocket, msg)
            except json.JSONDecodeError:
                logger.warning("[WS] Non-JSON message received")
    except websockets.exceptions.ConnectionClosedError:
        pass
    finally:
        _connected_clients.discard(websocket)
        logger.info(f"[WS] Client disconnected. Total: {len(_connected_clients)}")


async def _handle_message(websocket, msg: dict):
    msg_type = msg.get("type")

    if msg_type == "transcript":
        text = msg.get("text", "").strip()
        if text:
            logger.info(f"[WS] Transcript received: {text[:60]}")
            _transcript_queue.put(text)
            # Ack back so browser can show it
            await websocket.send(json.dumps({
                "type": "transcript_ack",
                "text": "You: " + text
            }))

    elif msg_type == "audio":
        # Raw PCM16 audio bytes for voice emotion detection
        try:
            audio_bytes = base64.b64decode(msg.get("data", ""))
            sample_rate = int(msg.get("sampleRate", 16000))
            _feed_audio_to_voice_detector(audio_bytes, sample_rate)
        except Exception as e:
            logger.warning(f"[WS] Audio decode error: {e}")


def _feed_audio_to_voice_detector(audio_bytes: bytes, sample_rate: int):
    """Pass PCM16 audio to voice_detector if it supports feed_audio_chunk."""
    try:
        detector = _get_voice_detector()
        if detector and hasattr(detector, "feed_audio_chunk"):
            audio_np = np.frombuffer(audio_bytes, dtype=np.int16)
            detector.feed_audio_chunk(audio_np, sample_rate=sample_rate)
    except Exception as e:
        logger.debug(f"[WS] Voice detector feed skipped: {e}")


_voice_detector_instance = None

def _get_voice_detector():
    global _voice_detector_instance
    if _voice_detector_instance is None:
        try:
            from perception.voice_detector import VoiceEmotionDetector
            _voice_detector_instance = VoiceEmotionDetector(use_transformer=True)
            logger.info("[WS] Voice detector created for browser audio feed")
        except Exception as e:
            logger.warning(f"[WS] Voice detector init failed: {e}")
            _voice_detector_instance = None
    return _voice_detector_instance

def set_voice_detector(detector):
    """Call this from main.py after creating the voice detector."""
    global _voice_detector_instance
    _voice_detector_instance = detector


# ── Broadcast helpers ─────────────────────────────────────────────────────

async def _broadcast(payload: dict):
    if not _connected_clients:
        return
    message = json.dumps(payload)
    # Send to all, ignore disconnected
    dead = set()
    for client in _connected_clients:
        try:
            await client.send(message)
        except Exception:
            dead.add(client)
    _connected_clients.difference_update(dead)


async def _flush_response_queue():
    """Drain response queue and broadcast to all clients."""
    while not _response_queue.empty():
        try:
            item = _response_queue.get_nowait()
        except queue.Empty:
            break

        if item.get("__type") == "emotion_update":
            await _broadcast({
                "type": "emotion_update",
                "emotions": item["emotions"]
            })
        else:
            await _broadcast({
                "type": "rio_response",
                "text": item["response_text"],
                "expression": item["expression"],
                "rio_state": item.get("rio_state", {}),
                "intervention_intent": item.get("intervention_intent", {}),
                "pipeline_feedback": item.get("pipeline_feedback", {}),
            })
            await _broadcast({
                "type": "play_audio",
                "url": item["audio_url"],
            })


# ── Server startup ────────────────────────────────────────────────────────

async def _run_server():
    global _loop
    _loop = asyncio.get_running_loop()
    logger.info("[WS] WebSocket server listening on ws://0.0.0.0:8765")
    async with websockets.serve(_handler, "0.0.0.0", 8765):
        await asyncio.Future()   # run forever


def start_ws_server() -> None:
    """Start WebSocket server in a background daemon thread."""
    def _thread():
        asyncio.run(_run_server())

    t = threading.Thread(target=_thread, daemon=True, name="ws-server")
    t.start()
    logger.info("[WS] Server thread started (daemon=True)")

